package com.emotion.ev;
import android.app.*;import android.os.*;import android.bluetooth.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 final int bg=0xff030508, panel=0xff151b24, cyan=0xff00e5ff, white=0xfff3f6fa; final Handler h=new Handler(); final ExecutorService io=Executors.newSingleThreadExecutor(); volatile BluetoothSocket socket; volatile boolean connected=false; volatile int generation=0; char direction='S'; int power=0; LinearLayout root,body; TextView status; String device=""; String page="Dashboard"; BluetoothAdapter adapter;
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 public void onCreate(Bundle b){super.onCreate(b);adapter=((BluetoothManager)getSystemService(BLUETOOTH_SERVICE)).getAdapter(); welcome();}
 GradientDrawable shape(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(18));d.setStroke(dp(1),0xff283344);return d;}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER);t.setPadding(dp(8),dp(10),dp(8),dp(10));return t;}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setGravity(Gravity.CENTER_HORIZONTAL);return l;}
 void base(){root=column();root.setBackgroundColor(bg);root.setPadding(dp(16),dp(36),dp(16),dp(28));setContentView(root);root.addView(text("E - M O T I O N",28,white));root.addView(text("DRIVE. GENERATE. INNOVATE.",12,cyan));}
 Button button(String s,int c,Runnable r){Button b=new Button(this);b.setText(s);b.setTextColor(c==cyan?bg:white);b.setBackground(shape(c));b.setOnClickListener(v->r.run());return b;}
 void add(LinearLayout l,View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(6),0,dp(6));l.addView(v,p);}
 void welcome(){base();root.addView(new Art(false),new LinearLayout.LayoutParams(-1,dp(240)));add(root,text("4WD ELECTRIC VEHICLE • MK-I",19,white));add(root,text("Bluetooth Classic • HC-05 • Arduino UNO",14,cyan));status=text("DISCONNECTED",14,white);add(root,status);add(root,button("CONNECT VEHICLE",cyan,()->choose()));}
 void choose(){if(adapter==null){status.setText("Bluetooth unavailable");return;}if(Build.VERSION.SDK_INT>=31&&checkSelfPermission(android.Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.BLUETOOTH_CONNECT},1);return;}if(!adapter.isEnabled()){startActivityForResult(new Intent(BluetoothAdapter.ACTION_REQUEST_ENABLE),2);return;}ArrayList<BluetoothDevice> ds=new ArrayList<>(adapter.getBondedDevices());if(ds.isEmpty()){status.setText("Pair HC-05 in Android Bluetooth settings first");return;}String[] names=new String[ds.size()];for(int i=0;i<ds.size();i++)names[i]=ds.get(i).getName()+"  "+ds.get(i).getAddress();new AlertDialog.Builder(this).setTitle("Select paired HC-05").setItems(names,(d,i)->connect(ds.get(i))).show();}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==1&&g.length>0&&g[0]==0)choose();}protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==2&&c==RESULT_OK)choose();}
 void connect(BluetoothDevice d){status.setText("CONNECTING…");int token=++generation;io.execute(()->{BluetoothSocket s=null;try{s=d.createRfcommSocketToServiceRecord(UUID.fromString("00001101-0000-1000-8000-00805F9B34FB"));socket=s;s.connect();if(token!=generation){s.close();return;}s.getOutputStream().write('S');connected=true;device=d.getName();h.post(()->{if(connected&&token==generation)main("Dashboard");});}catch(Exception e){if(s!=null)try{s.close();}catch(Exception ignored){}if(token==generation){connected=false;h.post(()->{welcome();status.setText("Connection failed — retry");});}}});}
 void send(char c){int token=generation;io.execute(()->{if(!connected||token!=generation)return;try{socket.getOutputStream().write(c);}catch(Exception e){connected=false;try{socket.close();}catch(Exception ignored){}h.post(()->{stop();welcome();status.setText("Connection lost");});}});}
 char speed(){return power==0?'0':power>90?'q':(char)('0'+(power+9)/10);}
 final Runnable pulse=new Runnable(){public void run(){if(direction!='S'&&connected){send(direction);h.postDelayed(this,200);}}};
 void stop(){direction='S';h.removeCallbacks(pulse);send('S');}void start(char c){if(!connected||direction!='S')return;direction=c;send(speed());h.post(pulse);}
 void disconnect(){stop();io.execute(()->{connected=false;generation++;try{if(socket!=null)socket.close();}catch(Exception ignored){}h.post(()->welcome());});}
 void main(String p){stop();page=p;base();add(root,text("CONNECTED • "+device,13,cyan));body=column();ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);for(String n:new String[]{"Dashboard","Drive","Energy","About"})nav.addView(button(n,n.equals(p)?cyan:panel,()->main(n)),new LinearLayout.LayoutParams(0,dp(52),1));root.addView(nav);if(p.equals("Dashboard")){body.addView(new Art(false),new LinearLayout.LayoutParams(-1,dp(230)));add(body,text("Commanded accelerator: "+power+"%\nNo live telemetry",18,white));add(body,button("START DRIVING",cyan,()->main("Drive")));add(body,button("DISCONNECT",0xff8c0d24,()->disconnect()));}else if(p.equals("Drive")){pad();}else if(p.equals("Energy")){body.addView(new Art(true),new LinearLayout.LayoutParams(-1,dp(240)));add(body,text("Wheel → Pulley → Belt → Dynamo → Electricity",18,cyan));add(body,text("Conceptual animation, not live sensor data. A dynamo converts mechanical energy to electrical energy, adds drag and cannot continuously recharge the drive battery without losses.",16,white));}else{add(body,text("E-MOTION • SCHOOL ENGINEERING PROJECT\n\nArduino UNO / HW-130 L293D / 4 BO motors / HC-05 / DC dynamo\n\nDifferential steering and energy conversion. Release-to-stop and firmware timeout. Future scope: measured telemetry and regulated energy recovery.",17,white));EditText credits=new EditText(this);credits.setTextColor(white);credits.setHint("Team credits");credits.setText(getPreferences(0).getString("credits","Team E-MOTION"));add(body,credits);add(body,button("SAVE CREDITS",cyan,()->getPreferences(0).edit().putString("credits",credits.getText().toString()).apply()));}}
 void pad(){add(body,text("HOLD TO DRIVE • RELEASE TO STOP",13,cyan));LinearLayout mid=new LinearLayout(this);mid.setGravity(Gravity.CENTER);body.addView(arrow('F',0),new LinearLayout.LayoutParams(dp(84),dp(84)));mid.addView(arrow('L',270),new LinearLayout.LayoutParams(dp(84),dp(84)));Button s=button("STOP",0xffd91e42,()->stop());s.setOnTouchListener((v,e)->{if(e.getActionMasked()==0)stop();return false;});mid.addView(s,new LinearLayout.LayoutParams(dp(84),dp(84)));mid.addView(arrow('R',90),new LinearLayout.LayoutParams(dp(84),dp(84)));body.addView(mid);body.addView(arrow('B',180),new LinearLayout.LayoutParams(dp(84),dp(84)));TextView t=text("ACCELERATOR • "+power+"%",20,cyan);add(body,t);SeekBar bar=new SeekBar(this);bar.setMax(100);bar.setProgress(power);add(body,bar);bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean u){power=v;t.setText("ACCELERATOR • "+v+"%");if(u)send(speed());}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});}
 View arrow(char cmd,int angle){View v=new View(this){Paint p=new Paint(3);protected void onDraw(Canvas c){float w=getWidth(),z=getHeight();c.save();c.translate(w/2,z/2);c.rotate(angle);float a=Math.min(w,z)*.32f;Path q=new Path();q.moveTo(0,-a);q.lineTo(a,0);q.lineTo(a*.4f,0);q.lineTo(a*.4f,a);q.lineTo(-a*.4f,a);q.lineTo(-a*.4f,0);q.lineTo(-a,0);q.close();p.setColor(isPressed()?white:cyan);c.drawPath(q,p);c.restore();}};v.setBackground(shape(panel));v.setContentDescription("Drive "+cmd);v.setOnTouchListener((x,e)->{switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:x.setPressed(true);x.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);start(cmd);return true;case MotionEvent.ACTION_UP:case MotionEvent.ACTION_CANCEL:x.setPressed(false);stop();return true;case MotionEvent.ACTION_MOVE:if(e.getX()<0||e.getY()<0||e.getX()>x.getWidth()||e.getY()>x.getHeight()){x.setPressed(false);stop();}return true;}return true;});return v;}
 protected void onPause(){stop();super.onPause();}protected void onDestroy(){stop();disconnect();super.onDestroy();}
 class Art extends View{Paint p=new Paint(3);boolean energy;Art(boolean e){super(MainActivity.this);energy=e;}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setColor(panel);if(!energy){float x=w/2,y=h/2;for(int i:new int[]{-1,1})for(int j:new int[]{-1,1})c.drawRoundRect(x+i*w*.14f-w*.045f,y+j*h*.24f-h*.10f,x+i*w*.14f+w*.045f,y+j*h*.24f+h*.10f,12,12,p);p.setColor(0xff283344);c.drawRoundRect(x-w*.13f,y-h*.43f,x+w*.13f,y+h*.43f,35,35,p);p.setColor(bg);c.drawRoundRect(x-w*.095f,y-h*.22f,x+w*.095f,y+h*.23f,20,20,p);p.setColor(cyan);c.drawRect(x-w*.09f,y-h*.38f,x+w*.09f,y-h*.35f,p);}else{float y=h/2;float a=(SystemClock.uptimeMillis()%2000)*.18f;p.setColor(cyan);p.setStrokeWidth(4);for(int i=0;i<3;i++){float x=w*(.17f+i*.32f),r=w*(i==0?.11f:.065f);p.setStyle(Paint.Style.STROKE);c.drawCircle(x,y,r,p);c.save();c.rotate(a,x,y);c.drawLine(x-r,y,x+r,y,p);c.restore();p.setStyle(Paint.Style.FILL);if(i<2)c.drawLine(x+r,y,x+w*.32f-r,y,p);}postInvalidateDelayed(33);}}}
}
